    @SubscribeEvent
    public static void onRegister(RegisterEvent event) {
        event.register(Registries.ENTITY_TYPE, helper -> {
            SIZES.forEach((id, size) -> {
                EntityType<MergedVehicleEntity> type = EntityType.Builder
                        .<MergedVehicleEntity>of(MergedVehicleEntity::new, MobCategory.MISC)
                        .setTrackingRange(512)
                        .setUpdateInterval(1)
                        .fireImmune()
                        .sized(size[0], size[1])
                        .build(id);
                helper.register(ResourceLocation.fromNamespaceAndPath(SbwVlsMod.MODID, id), type);
                TYPES.put(id, type);
            });
        });
    }

    private MergedVehicles() {}
